-- Pathbuilder: the road now starts at the house and is built out to the car, which then drives the whole road home
-- (what our young beta testers asked for). Its How to play on the Play page and in the Subscriber's Portal.
-- Run once in the Supabase SQL Editor (safe to run again).
update games set data = data || jsonb_build_object('rules', $r$["Your house is at the start, and the car is waiting across the island. Build a road from your house all the way to the car.", "Pick a road card, then click a square next to the end of your road. Turn the card with the Turn button or the R key.", "Roads only connect edge to edge, so line the openings up.", "When your road reaches the car, the car drives the whole road home to your house.", "Rivers need a bridge card. A bridge can also sit on grass or go over another road, as long as it crosses the road and does not run along it.", "Trees and rocks are in the way, so plan around them. Medium and Hard are bigger islands with more to avoid.", "Stuck? Press Swap my cards for a whole new hand, Undo your last card, or Go back if the road ends.", "The par is the shortest road possible. Use about that many cards to earn three stars.", "Switch between the 3D view and a top-down 2D view, and turn the board a quarter at a time with the arrow buttons or Q and E.", "For 2 players, choose 2 players, then make a room and share the 6-character code. Your friend types it under Join a friend. You both build at the same time, and the first road to reach your car wins.", "Pick Set stage for the same island every time, or Random map for a new one.", "Sound is on: press the speaker button to turn it off."]$r$::jsonb), updated_at = now()
where id = 'game-pathbuilder';
update portal_entries set data = data || jsonb_build_object('howToPlay', $r$["Your house is at the start, and the car is waiting across the island. Build a road from your house all the way to the car.", "Pick a road card, then click a square next to the end of your road. Turn the card with the Turn button or the R key.", "Roads only connect edge to edge, so line the openings up.", "When your road reaches the car, the car drives the whole road home to your house.", "Rivers need a bridge card. A bridge can also sit on grass or go over another road, as long as it crosses the road and does not run along it.", "Trees and rocks are in the way, so plan around them. Medium and Hard are bigger islands with more to avoid.", "Stuck? Press Swap my cards for a whole new hand, Undo your last card, or Go back if the road ends.", "The par is the shortest road possible. Use about that many cards to earn three stars.", "Switch between the 3D view and a top-down 2D view, and turn the board a quarter at a time with the arrow buttons or Q and E.", "For 2 players, choose 2 players, then make a room and share the 6-character code. Your friend types it under Join a friend. You both build at the same time, and the first road to reach your car wins.", "Pick Set stage for the same island every time, or Random map for a new one.", "Sound is on: press the speaker button to turn it off."]$r$::jsonb), updated_at = now()
where id = 'portal-pathbuilder';
